SELECT 1\\n        FROM   RDS_WV_ORDLOC    ol2\\n        JOIN   RDS_WV_ORDHEAD   oh2\\n            ON  oh2.ORDER_NO    = ol2.ORDER_NO\\n        WHERE\\n            ol2.ITEM            = ril.ITEM\\n            AND ol2.LOCATION    = ril.LOCATION\\n            AND oh2.ORDER_TYPE  IN ('ARB', 'BRB')\\n            AND NVL(ol2.QTY_RECEIVED, 0) &gt; 0\\n    )\\n\\nORDER BY\\n    days_since_order            DESC,\\n    ril.LOCATION,\\n    im.DEPT,\\n    im.ITEM,\\n    oh.ORDER_NO;\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-06-29T05:57:15.411+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'OracleRetailCloudAdmin@deloitte.com'.'RPT_075 Items on Repl never Receieved'","parent-namespace":"OracleRetailCloudAdmin@deloitte.com","parent-name":"RPT_075 Items on Repl never Receieved","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"OracleRetailCloudAdmin@deloitte.com","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'OracleRetailCloudAdmin@deloitte.com'.'RPT_075 Items on Repl never Receieved'"}
